    for(int i = start; i <= end; i++) { 
        boolean isPrime = true; 

        for(int j = 2; j < i; j++) { 
            if(i % j == 0) { 
                isPrime = false; 
                break;
            } 
        } 

        if(isPrime) { 
            System.out.print(i + " "); 
        }
    }  
}

