import json

def parse_json_file(json_file):
    with open(json_file, 'r') as f:
        json_content = json.load(f)

    return parse_json_object(json_content)

def parse_json_object(json_obj):
    if isinstance(json_obj, (list, tuple)):
        return [parse_json_object(item) for item in json_obj]
    elif isinstance(json_obj, dict):
        return {key: parse_json_object(value) for key, value in json_obj.items()}
    else:
        return json_obj
